## If you must keep synchronous threads

```csharp
public class EventProcessor : IDisposable
{
    private readonly CancellationTokenSource _cts = new();
    private readonly ManualResetEventSlim _newEvent = new(false);
    private readonly Queue<string> _queue = new();
    private readonly object _lock = new();
    private Thread? _thread;

    public void Start()
    {
        _thread = new Thread(RunLoop);
        _thread.Start();
    }

    private void RunLoop()
    {
        var handles = new[] { _newEvent.WaitHandle, _cts.Token.WaitHandle };
        while (!_cts.Token.IsCancellationRequested)
        {
            WaitHandle.WaitAny(handles); // wakes on new item OR cancellation
            _newEvent.Reset();

            while (TryDequeue(out var item))
            {
                Handle(item);
            }
        }
    }

    private bool TryDequeue(out string item)
    {
        lock (_lock)
        {
            if (_queue.Count > 0) { item = _queue.Dequeue(); return true; }
            item = default!; return false;
        }
    }

    public void Enqueue(string item)
    {
        lock (_lock) { _queue.Enqueue(item); }
        _newEvent.Set();
    }

    public void Stop()
    {
        _cts.Cancel();                // wakes WaitAny via token.WaitHandle
        _thread?.Join(5000);          // wait for graceful exit
        // No Thread.Abort fallback — thread will exit at next WaitAny check
    }

    public void Dispose()
    {
        _cts.Dispose();
        _newEvent.Dispose();
    }

    private void Handle(string item) { /* your logic */ }
}
```

